# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEKNOLOJİ FELSEFESİNDE ONTOLOJİK VE AKSİYOLOJİK PROBLEMLER</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. ONTOLOJİK (VARLIKSAL) PROBLEMLER</text>\n  <rect x="35" y="78" width="290" height="128" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">• Ontolojik Anlam Kaybı (Heidegger):</text>\n  <text x="180" y="113" text-anchor="middle" font-size="9.5" fill="#334155">Doğa ve insanın salt bir enerji/veri stoğu görülmesi.</text>\n  <text x="180" y="133" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">• Yabancılaşma ve Simülasyon (Baudrillard):</text>\n  <text x="180" y="148" text-anchor="middle" font-size="9.5" fill="#334155">Sanal gerçekliğin asıl gerçekliğin yerini alması.</text>\n  <text x="180" y="168" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">• Transhümanizm ve Yapay Zekâ Bilinci:</text>\n  <text x="180" y="183" text-anchor="middle" font-size="9.5" fill="#334155">İnsan doğasının biyoteknoloji ile dönüştürülmesi.</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. AKSİYOLOJİK (ETİK / DEĞER) PROBLEMLER</text>\n  <rect x="375" y="78" width="290" height="128" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• Güvenlik ve Mahremiyetin Tahribatı:</text>\n  <text x="520" y="113" text-anchor="middle" font-size="9.5" fill="#334155">Büyük veri (Big Data) gözetimi ve özel hayatın ihlali.</text>\n  <text x="520" y="133" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• Ahlaki Eylemin İmkânı ve Sorumluluk:</text>\n  <text x="520" y="148" text-anchor="middle" font-size="9.5" fill="#334155">Otonom sistemlerin kararlarından kimin sorumlu olduğu.</text>\n  <text x="520" y="168" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• Gelecek Kuşaklara Karşı Sorumluluk (Jonas):</text>\n  <text x="520" y="183" text-anchor="middle" font-size="9.5" fill="#334155">Ekolojik yıkım ve biyogenetik risklerin önlenmesi.</text>\n</svg>', '<svg viewBox="0 0 700 210" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="210" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YAPAY ZEKÂ VE TEKNOLOJİ ETİĞİNDE TEMEL TARTIŞMALAR</text>\n  <rect x="20" y="48" width="210" height="142" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#3730a3">AHLAKİ ÖZNE SORUNU</text>\n  <text x="125" y="96" text-anchor="middle" font-size="10" fill="#334155">• Yapay zekâ bilinç ve özgür</text>\n  <text x="125" y="112" text-anchor="middle" font-size="10" fill="#334155">iradeye sahip olabilir mi?</text>\n  <text x="125" y="134" text-anchor="middle" font-size="10" fill="#334155">• Otonom kararların hukuki ve</text>\n  <text x="125" y="150" text-anchor="middle" font-size="10" fill="#334155">vicdani sorumlusu kimdir?</text>\n\n  <rect x="245" y="48" width="210" height="142" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">ALGORİTMİK TAHAKKÜM</text>\n  <text x="350" y="96" text-anchor="middle" font-size="10" fill="#334155">• Yankı odaları ve algoritmik</text>\n  <text x="350" y="112" text-anchor="middle" font-size="10" fill="#334155">yönlendirme özgür iradeyi</text>\n  <text x="350" y="128" text-anchor="middle" font-size="10" fill="#334155">nasıl sınırlandırır?</text>\n  <text x="350" y="150" text-anchor="middle" font-size="10" fill="#334155">• Veri mahremiyeti ve gözetim.</text>\n\n  <rect x="470" y="48" width="210" height="142" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">HANS JONAS: SORUMLULUK</text>\n  <text x="575" y="96" text-anchor="middle" font-size="10" fill="#334155">• Ekolojik denge ve gelecek</text>\n  <text x="575" y="112" text-anchor="middle" font-size="10" fill="#334155">nesillerin var olma hakkı.</text>\n  <text x="575" y="134" text-anchor="middle" font-size="10" fill="#334155">• Teknolojik güce sınır koyan</text>\n  <text x="575" y="150" text-anchor="middle" font-size="10" fill="#334155">yeni evrensel ahlak yasası.</text>\n</svg>', '<svg viewBox="0 0 700 230" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="230" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AKIL VE İNANÇ İLİŞKİSİNDE TEMEL FELSEFİ YAKLAŞIMLAR</text>\n  <rect x="20" y="48" width="210" height="162" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="125" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">1. FİDEİZM (İNANÇÇILIK)</text>\n  <text x="125" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Tertullianus &amp; Kierkegaard</text>\n  <text x="125" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• İnanç akla dayanmaz, aklın</text>\n  <text x="125" y="130" text-anchor="middle" font-size="9.5" fill="#334155">sınırlarını aşan bir sıçramadır.</text>\n  <text x="125" y="152" text-anchor="middle" font-size="9.5" fill="#334155">• \'Saçma (akıl almaz) olduğu</text>\n  <text x="125" y="168" text-anchor="middle" font-size="9.5" fill="#334155">için inanıyorum\' (Tertullianus).</text>\n\n  <rect x="245" y="48" width="210" height="162" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. UZLAŞTIRMACI YAKLAŞIM</text>\n  <text x="350" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">İbn Rüşd, Fârâbî, Aquinolu Thomas</text>\n  <text x="350" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Akıl ve vahiy aynı ilahi</text>\n  <text x="350" y="130" text-anchor="middle" font-size="9.5" fill="#334155">kaynaktan gelir, çelişmez.</text>\n  <text x="350" y="152" text-anchor="middle" font-size="9.5" fill="#334155">• \'Hakikat hakikate ters düşmez\'</text>\n  <text x="350" y="168" text-anchor="middle" font-size="9.5" fill="#334155">(İbn Rüşd - Faslü\'l-Makâl).</text>\n\n  <rect x="470" y="48" width="210" height="162" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="575" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">3. ANLAMAK İÇİN İNANMAK</text>\n  <text x="575" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Augustinus &amp; Anselmus</text>\n  <text x="575" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• İnanç anlamanın ön koşuludur;</text>\n  <text x="575" y="130" text-anchor="middle" font-size="9.5" fill="#334155">akıl ise inanılan şeyi açıklar.</text>\n  <text x="575" y="152" text-anchor="middle" font-size="9.5" fill="#334155">• \'Anlamak için inanıyorum\'</text>\n  <text x="575" y="168" text-anchor="middle" font-size="9.5" fill="#334155">(Credo ut intelligam).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
